using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace GameDailyWidget;

public sealed partial class MainWindow
{
    // Include text generated by control templates. Detached preview trees have
    // IsVisible=false even when their content will be painted to the bitmap.
    private static IEnumerable<TextBlock> VisibleText(DependencyObject node)
    {
        if (node is UIElement { Visibility: not Visibility.Visible }) yield break;
        if (node is TextBlock text && text.Text.Length > 0 && text.ActualWidth > 0 && text.ActualHeight > 0)
            yield return text;
        for (int i = 0; i < VisualTreeHelper.GetChildrenCount(node); i++)
            foreach (var child in VisibleText(VisualTreeHelper.GetChild(node, i))) yield return child;
    }

    private static double TextWidth(TextBlock text) => new FormattedText(text.Text, CultureInfo.InvariantCulture,
        text.FlowDirection, new Typeface(text.FontFamily, text.FontStyle, text.FontWeight, text.FontStretch),
        text.FontSize, text.Foreground, VisualTreeHelper.GetDpi(text).PixelsPerDip).WidthIncludingTrailingWhitespace;

    internal void CheckWuwaPoolPanel()
    {
        var labels=VisibleText(_poolsPanel).ToList();
        var headings=labels.Where(t=>t.Text.StartsWith("当前开放 · ")).Select(t=>t.Text);
        if (!headings.SequenceEqual(["当前开放 · 新 UP","当前开放 · 复刻","当前开放 · 忆旅"]) ||
            !labels.Any(t=>t.Text=="4星：星河、晴空" && t.FontSize<=10 && Equals(t.Foreground,FaceMuted)) ||
            !labels.Any(t=>t.Text.EndsWith(" *") && t.ToolTip?.ToString()?.Contains("公告元数据")==true))
            throw new InvalidOperationException("鸣潮卡池分组、四星行或元数据标注缺失");
        _detailScroll.ScrollToBottom();
        _detailScroll.UpdateLayout();
        if (_detailScroll.ScrollableHeight-_detailScroll.VerticalOffset>.1)
            throw new InvalidOperationException("卡池末行无法滚动到达");
        _detailScroll.ScrollToTop();
        _detailScroll.UpdateLayout();
    }

    internal object CheckSkinLayout()
    {
        var labels = new List<(Rect Bounds, TextBlock Label)>();
        var card = new Rect(_card.RenderSize);
        foreach (var label in VisibleText(_card))
        {
            var size = new Size(Math.Min(TextWidth(label), label.ActualWidth), label.ActualHeight);
            var bounds = label.TransformToAncestor(_card).TransformBounds(new Rect(size));
            if (_expanded && label.IsDescendantOf(_detailScroll))
            {
                var viewport = _detailScroll.TransformToAncestor(_card).TransformBounds(new Rect(_detailScroll.RenderSize));
                bounds.Intersect(viewport);
                if (bounds.IsEmpty) continue;
            }
            if (!card.Contains(bounds))
                throw new InvalidOperationException($"文字超出卡片 {label.Text} {bounds}");
            foreach (var other in labels)
            {
                var intersection = Rect.Intersect(bounds, other.Bounds);
                if (!intersection.IsEmpty && intersection.Width > 1 && intersection.Height > 1)
                    throw new InvalidOperationException($"文字相互遮挡 {label.Text} / {other.Label.Text} {intersection}");
            }
            labels.Add((bounds, label));
        }
        if (labels.Count < 10 || _segments.TransformToAncestor(_footer).TransformBounds(new Rect(_segments.RenderSize)).Right
            >= _eventsButton.TranslatePoint(new Point(), _footer).X)
            throw new InvalidOperationException("卡片文字或页脚布局异常");
        Rect Bounds(FrameworkElement element) =>
            element.TransformToAncestor(_card).TransformBounds(new Rect(element.RenderSize));
        var layoutBounds = Bounds(_layout);
        var layoutClip = System.Windows.Controls.Primitives.LayoutInformation.GetLayoutClip(_layout);
        var footerGap = card.Bottom - Bounds(_footer).Bottom;
        if (layoutClip != null || !card.Contains(layoutBounds) ||
            Math.Abs(footerGap - (_layout.Margin.Bottom + _card.BorderThickness.Bottom)) > .01)
            throw new InvalidOperationException($"卡片裁切：卡片 {card}，布局 {layoutBounds}，裁切 {layoutClip?.Bounds}，页脚下边距 {footerGap:F2}");

        // Separate transforms of a shared edge can differ at floating-point precision.
        static bool Contains(Rect outer, Rect inner) =>
            Math.Round(inner.Left - outer.Left, 6) >= 0 && Math.Round(inner.Top - outer.Top, 6) >= 0 &&
            Math.Round(outer.Right - inner.Right, 6) >= 0 && Math.Round(outer.Bottom - inner.Bottom, 6) >= 0;
        var controls = 0;
        void CheckControls(DependencyObject parent)
        {
            for (var i = 0; i < VisualTreeHelper.GetChildrenCount(parent); ++i)
            {
                var child = VisualTreeHelper.GetChild(parent,i);
                if (child is UIElement { Visibility: not Visibility.Visible }) continue;
                if (child is FrameworkElement element && element.ActualWidth > 0 && element.ActualHeight > 0 &&
                    (element is Control || element == _segments || element == _streakChip || element == _warningChip || element == _versionBar))
                {
                    var rect = Bounds(element);
                    if (element.IsDescendantOf(_details) || element.IsDescendantOf(_eventsPanel) || element.IsDescendantOf(_poolsPanel))
                    {
                        var viewport = Bounds(_detailScroll);
                        if (rect.Left < viewport.Left - .01 || rect.Right > viewport.Right + .01)
                            throw new InvalidOperationException("面板行超出可用宽度");
                        rect.Intersect(viewport);
                    }
                    if (!rect.IsEmpty && (!Contains(card,rect) || element.IsDescendantOf(_layout) && !Contains(layoutBounds,rect)))
                        throw new InvalidOperationException($"控件超界 {element.GetType().Name} {rect}；布局 {layoutBounds}");
                    ++controls;
                }
                CheckControls(child);
            }
        }
        CheckControls(_card);
        if(IsEndfield)
        {
            RefreshDepth();
            foreach(var p in _depth.Plates)
            {
                var shadow=p.Bounds; shadow.Offset(p.Tile?10:p.Offset,p.Tile?10:p.Offset);
                if(!Contains(new Rect(_depth.RenderSize),shadow)) throw new InvalidOperationException("叠板超出卡片");
            }
            foreach(var b in new[]{_expand,_eventsButton,_poolsButton})
                if(b.RenderTransform.Value.OffsetX!=(IsPanelDown(b)?2:0)) throw new InvalidOperationException("展开按钮按下态异常");
        }
        return new { game = _currentGame, scale = _settings.Scale, panel = _eventsOpen ? "events" : _poolsOpen ? "pools" : _expanded ? "details" : "compact",
            labels = labels.Count, controls, width = _card.ActualWidth, height = _card.ActualHeight, footerGap,
            layoutClipped = layoutClip != null, scrollbar = _expanded && _detailScroll.ComputedVerticalScrollBarVisibility == Visibility.Visible,
            viewport = _expanded ? _detailScroll.ViewportHeight : 0, extent = _expanded ? _detailScroll.ExtentHeight : 0 };
    }

    internal void CheckDetailsScroll(bool expected)
    {
        var scroll = _detailScroll;
        if (scroll.ComputedVerticalScrollBarVisibility == Visibility.Visible != expected ||
            scroll.ExtentWidth > scroll.ViewportWidth + .01 ||
            (!expected && Math.Abs(scroll.ViewportHeight - scroll.ExtentHeight) > .01))
            throw new InvalidOperationException($"详情视口异常 {scroll.ViewportWidth}/{scroll.ExtentWidth} {scroll.ViewportHeight}/{scroll.ExtentHeight}");
        scroll.ScrollToEnd();
        scroll.UpdateLayout();
        if (scroll.VerticalOffset + scroll.ViewportHeight < scroll.ExtentHeight - .1)
            throw new InvalidOperationException("详情末行无法到达");
        scroll.ScrollToTop();
        scroll.UpdateLayout();
    }

    internal void CheckClaimAppearance()
    {
        var check = new CheckBox { Template = ClaimTemplate(), IsChecked = false };
        check.ApplyTemplate();
        var box = (Border)check.Template.FindName("Box", check);
        var mark = (System.Windows.Shapes.Path)check.Template.FindName("Mark", check);
        static string ColorOf(Brush brush) => ((SolidColorBrush)brush).Color.ToString();
        if (ColorOf(box.Background) != (IsEndfield ? "#FFFAFAF6" : "#A0111022") ||
            ColorOf(box.BorderBrush) != (IsEndfield ? "#FF141414" : "#FFD6BB87") ||
            box.CornerRadius != new CornerRadius(IsEndfield ? 0 : 2) ||
            box.BorderThickness != new Thickness(1) || mark.Visibility != Visibility.Hidden)
            throw new InvalidOperationException("未勾选的活动样式异常");
        check.IsChecked = true;
        if (mark.Visibility != Visibility.Visible || ColorOf(mark.Stroke) != (IsEndfield ? "#FFF5E200" : "#FFF3D9A1") ||
            ColorOf(box.Background) != (IsEndfield ? "#FF141414" : "#A0111022"))
            throw new InvalidOperationException("已勾选的活动样式异常");
        var triggers = check.Template.Triggers.OfType<Trigger>();
        bool Changes(DependencyProperty state, DependencyProperty property, object value) =>
            triggers.Any(t => t.Property == state && Equals(t.Value,true) && t.Setters.OfType<Setter>()
                .Any(s => s.TargetName == "Box" && s.Property == property &&
                    (s.Value is Brush brush ? Equals(ColorOf(brush), value) : Equals(s.Value,value))));
        if (!Changes(IsMouseOverProperty,Border.BorderBrushProperty,IsEndfield ? "#FF756800" : "#FFF3E3BD") ||
            !Changes(IsKeyboardFocusedProperty,Border.BorderThicknessProperty,new Thickness(2)))
            throw new InvalidOperationException("勾选框悬停或键盘焦点反馈异常");
    }

    internal void CheckLongNames()
    {
        foreach (var (text, tip) in new[] { (_version, _versionBar.ToolTip), (_accountName, _account.ToolTip), (_summary, _summaryButton.ToolTip) })
            if (text.TextTrimming != TextTrimming.CharacterEllipsis || TextWidth(text) <= text.ActualWidth ||
                tip is not string full || !full.Contains("长名长名长名", StringComparison.Ordinal))
                throw new InvalidOperationException("长名称必须省略并保留悬停全文 " + text.Text);
    }
}

internal static class SkinChecks
{
    private sealed class Fake(string key, string nickname) : IGameController
    {
        public string GameKey => key;
        public GameViewState State { get; set; } = new()
        {
            GameKey = key,
            Nickname = nickname,
            IdentityLabel = "演示账号甲",
            CopyIdentity = "demo-identity",
            Accounts = [new("a", nickname), new("b", "演示账号乙")],
            SelectedAccountKey = "a",
            LoggedIn = true,
            Stamina = 30,
            MaxStamina = 100,
            Daily = 22,
            MaxDaily = 100,
            DailyState = "incomplete",
            FullAt = DateTimeOffset.UtcNow.AddHours(4)
        };
        public string? Selected;
        public int LoginCalls;
        public event Action? Changed { add { } remove { } }
        public Task InitializeAsync() => Task.CompletedTask;
        public Task RefreshAsync() => Task.CompletedTask;
        public Task SelectAccountAsync(string account) { Selected = account; return Task.CompletedTask; }
        public Task LoginAsync(Window? owner) { LoginCalls++; return Task.CompletedTask; }
        public void Logout() { }
        public void SetRefreshMinutes(int minutes) { }
        public void Dispose() { }
    }

    internal static IEnumerable<string> Run()
    {
        var results = new List<string>();
        string longName = string.Concat(Enumerable.Repeat("长名", 45));
        foreach (var key in new[] { "wuwa", "endfield" })
        {
            var settings = UnifiedSettings.Load(true);
            settings.CurrentGame = key;
            var fake = new Fake(key, longName);
            var other = new Fake(key == "wuwa" ? "endfield" : "wuwa", "其他演示账号");
            string? copied = null;
            var widget = new MainWindow(settings, key == "wuwa" ? fake : other, key == "endfield" ? fake : other,
                false, () => TimeZoneInfo.Utc, value => copied = value);
            try
            {
                if (!widget.IsOverview || widget.Width != 560) throw new InvalidOperationException("启动总览或默认宽度异常");
                widget.OpenGamePage(key);
                if (widget.IsOverview || widget.Width != 560) throw new InvalidOperationException("总览进入单游戏时宽度发生变化");
                widget.CheckClaimAppearance();
                results.Add("PASS " + key + " 已领完的两种实际模板状态、悬停和焦点反馈");
                var menu = widget.AccountMenuForPreview();
                var items = menu.Items.OfType<MenuItem>().ToArray();
                if (items.Length != 4 || !items[0].IsChecked || items[1].IsChecked || !items.All(i => i.IsEnabled))
                    throw new InvalidOperationException("账号菜单未呈现全部命令");
                menu.Measure(new Size(double.PositiveInfinity, double.PositiveInfinity));
                menu.Arrange(new Rect(menu.DesiredSize));
                if (menu.ActualWidth > 340 || items[0].Header is not TextBlock { TextTrimming: TextTrimming.CharacterEllipsis } ||
                    items[0].ToolTip as string != longName)
                    throw new InvalidOperationException("过长的账号菜单项必须限制宽度并保留全文");
                foreach (var item in items.Skip(1)) item.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));
                if (fake.Selected != "b" || fake.LoginCalls != 1 || copied != "demo-identity")
                    throw new InvalidOperationException("账号切换、复制和登录命令没有送达对应目标");
                var store = new EventStore();
                var now = DateTimeOffset.UtcNow;
                if (key=="wuwa") EventPreviewData.WuwaPools(store.Data,now,"metadata");
                string title = "「" + longName + "」" + (key == "wuwa" ? "3.8版本内容说明" : "版本更新说明");
                store.Data.Articles[key + ":demo"] = new(now, now, Title: title);
                store.Data.Events.Add(new("demo", key, longName, "演示", now.AddDays(-1), now.AddHours(2), false, null,
                    new("演示奖励", null), new("demo", "演示公告", ""), "演示", now.AddDays(-1)));
                widget.BindEvents(store, null);
                widget.SetStreakText("连续达标 3 天 · 演示记录");
                var card = (FrameworkElement)widget.Content;
                widget.Content = null;
                void Arrange()
                {
                    var size = new Size(widget.Width, widget.Height);
                    card.Measure(size); card.Arrange(new Rect(size)); card.UpdateLayout();
                    widget.CheckSkinLayout();
                }
                fake.State = fake.State with { Details = [new("短项目","短数值")] };
                widget.RenderAll();
                foreach (double scale in new[] { .5, 1, 1.5, 2.5 })
                {
                    widget.SetScale(scale);
                    Arrange();
                    widget.CheckLongNames();
                    widget.ToggleDetails();
                    Arrange();
                    widget.CheckDetailsScroll(false);
                    widget.OpenEvents();
                    Arrange();
                    widget.CheckEventLayout();
                    widget.OpenPools();
                    Arrange();
                    if (key=="wuwa") widget.CheckWuwaPoolPanel();
                    widget.ToggleDetails();
                    widget.ToggleDetails();
                }
                results.Add("PASS " + key + " 账号命令、四档缩放下四种面板的控件边界、页脚间距和长名称");
                widget.SetScale(1);
                widget.ToggleDetails();
                fake.State = fake.State with { Details = [new(longName,longName,longName)] };
                widget.RenderAll();
                Arrange();
                fake.State = fake.State with { Details = Enumerable.Range(1,60).Select(i => new DetailLine("长列表","演示行 " + i)).ToArray() };
                widget.RenderAll();
                Arrange();
                widget.CheckDetailsScroll(true);
                double manyHeight = widget.Height;
                widget.ShowGame(other.GameKey,false);
                Arrange();
                if (widget.Height >= manyHeight) throw new InvalidOperationException("详情翻面后未按短内容缩小");
                widget.ShowGame(key,false);
                Arrange();
                if (widget.Height != manyHeight) throw new InvalidOperationException("详情翻回后未恢复测量高度");
                results.Add("PASS " + key + " 长详情文本、多行滚动可达、短面板贴合内容及展开翻面重测");
            }
            finally { widget.PermitClose(); widget.Close(); }
        }
        return results;
    }
}
